package com.smartlibrary.algorithms.complexity;import java.util.*;
public final class Optimization {private Optimization(){}public record KnapsackResult(int value,List<Integer> indices){}public static KnapsackResult knapsack(int[] weights,int[] values,int cap){if(weights.length!=values.length||cap<0)throw new IllegalArgumentException();int n=weights.length;if(n>30)throw new IllegalArgumentException("Use at most 30 items for bitmask exact search");int best=0,bmask=0;for(int mask=0;mask<(1<<n);mask++){int w=0,v=0;for(int i=0;i<n;i++)if((mask&(1<<i))!=0){w+=weights[i];v+=values[i];}if(w<=cap&&v>best){best=v;bmask=mask;}}List<Integer> ids=new ArrayList<>();for(int i=0;i<n;i++)if((bmask&(1<<i))!=0)ids.add(i);return new KnapsackResult(best,ids);}public static Set<Integer> vertexCoverApprox(int n,int[][] edges){Set<Integer> cover=new LinkedHashSet<>();boolean[] used=new boolean[edges.length];for(int i=0;i<edges.length;i++)if(!used[i]){int u=edges[i][0],v=edges[i][1];if(u<0||v<0||u>=n||v>=n)throw new IllegalArgumentException("Invalid edge");cover.add(u);cover.add(v);for(int j=0;j<edges.length;j++)if(edges[j][0]==u||edges[j][1]==u||edges[j][0]==v||edges[j][1]==v)used[j]=true;}return cover;}public static boolean isVertexCover(Set<Integer> c,int[][] e){for(int[] x:e)if(!c.contains(x[0])&&!c.contains(x[1]))return false;return true;}}
